package com.company.platform.inventory.api;
import com.company.platform.inventory.application.WarehouseService;import com.company.platform.inventory.domain.Warehouse;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/warehouses") public class WarehouseController{private final WarehouseService service;public WarehouseController(WarehouseService s){service=s;}public record WarehouseRequest(String code,String name){}@PostMapping public Warehouse create(@RequestBody WarehouseRequest r){return service.create(r.code(),r.name());}@GetMapping public List<Warehouse> list(){return service.list();}@GetMapping("/{id}")public Warehouse get(@PathVariable UUID id){return service.get(id);}@PutMapping("/{id}")public Warehouse update(@PathVariable UUID id,@RequestBody WarehouseRequest r){return service.update(id,r.code(),r.name());}}
